     <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
 </head>
 <body>
     <div id="root"></div>
     <script type="text/babel">
 const { useState } = React;

 const ConsentForm = () => {
     const [agreed, setAgreed] = useState(false);
     const [submitted, setSubmitted] = useState(false);

     const handleSubmit = (e) => {
         e.preventDefault();
         // Browser validation handles the 'required' state
         setSubmitted(true);
     };

     return (
         <div className="container">
             <a href="#main-content" className="skip-link">Skip to main content</a>
             <main id="main-content" className="form-card">
                 <header>
                     <h1>User Consent</h1>
                     <p className="form-description">Please accept our terms to proceed with your registration.</p>
                 </header>

                 <form onSubmit={handleSubmit}>
                     <p className="required-note" aria-hidden="true">
                         Fields marked with <span className="required">*</span> are required
                     </p>

                     <div className="form-field">
                         <div className="checkbox-container">
                             <input
                                 id="consent-checkbox"
                                 type="checkbox"
                                 name="consent"
                                 required
                                 checked={agreed}
                                 onChange={(e) => {
                                     setAgreed(e.target.checked);
                                     if (submitted) setSubmitted(false);
                                 }}
                                 aria-describedby="consent-help"
                             />
                             <label htmlFor="consent-checkbox">
                                 I agree to the <a href="#" onClick={(e) => e.preventDefault()}>Terms of Use</a>
                                 <span className="required" aria-hidden="true">*</span>
                             </label>
                         </div>
                         <p id="consent-help" className="helper-text">
                             Checking this box means you agree to our service terms and privacy policy.
                         </p>
                     </div>

                     <button type="submit" className="submit-btn">
                         Agree and Continue
                     </button>

                     {submitted && (
                         <div className="success-message" role="status">
                             <span aria-hidden="true">✅</span> Your consent has been recorded. Thank you!
                         </div>
                     )}
                 </form>
             </main>
         </div>
     );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ConsentForm />);
     </script>
 </body>
 </html>

')
